"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'A Season for Love', 'author': 'Signature original', 'genre': 'Historical Romance', 'chapters': [{'n': 1, 'title': 'Homecoming', 'text': "Claire Bennett hadn't meant to come back to the coastal town of Seabrook. The city had been fine — fine in the way a waiting room is fine. But the letter about the old house, and a plane ticket tucked inside it, had pulled her home like a tide.\n\nHe was there — the boy from that summer, grown into a man with the same laugh. Time folded. Claire Bennett's heart, so carefully guarded, did something reckless: it hoped.\n\nThat evening she walked to the shore, a plane ticket in her pocket. The sunset did what the coastal town of Seabrook sunsets always did: made her feel everything at once. She wasn't alone long."}, {'n': 2, 'title': 'The Thing Remembered', 'text': "her ex Daniel — the reason she'd left, the shadow over it all — was still there, in the past where it belonged. Claire Bennett felt it loosen its grip. love is worth the risk, she thought. Maybe. Just maybe.\n\nThey talked until the shop closed, until the streetlights came on in the coastal town of Seabrook. Seventeen years of almosts poured out: the almost-letters, the almost-calls, the life they'd almost shared.\n\nher best friend Jess listened to the whole story over coffee and said what best friends say: 'You have to talk to him.' Claire Bennett said she couldn't. her best friend Jess said she must. They were both right."}, {'n': 3, 'title': 'Complications', 'text': "her best friend Jess was blunt: 'People don't change. They just get better at hiding.' But Claire Bennett had changed — hadn't she? The question followed her through the farmers market, past the wildflowers, into her dreams.\n\na plane ticket sat on her dresser, accusing and comforting by turns. She picked it up and finally understood what it was: not a map to the past, but permission for the future.\n\nHe — the bookshop man, the summer boy — went quiet. Not angry, just hurt, in the way of someone who's waited seventeen years and can wait no longer. Claire Bennett felt the old panic rise: run, before it breaks."}, {'n': 4, 'title': 'The Choice', 'text': "a plane ticket got a place of honor on the mantel — not as a relic, but as a reminder: that love lost can be love found, that love is worth the risk, and that home was never a town at all.\n\nShe found him at the shore, where it started. 'I choose,' she said, breathless, 'the thing that scares me. I choose you. I've always chosen you — I just took seventeen years to say it.'\n\nher best friend Jess cried at the news and denied it. The whole of the coastal town of Seabrook seemed to conspire in their happiness: the bookshop stayed open late, the bakery made a cake, the wildflowers bloomed on schedule."}, {'n': 5, 'title': 'The Promise', 'text': "The wedding was in the coastal town of Seabrook, in the season of wildflowers. Her grandmother Rose's quilt was on the bed. her best friend Jess gave a speech that made everyone cry laughing.\n\nlove is worth the risk — Claire Bennett wrote it in the new journal, the one for the next seventeen years. In the coastal town of Seabrook, under the stars, with love: the whole story, and only just beginning.\n\nLate that night, on the shore, they stood where the boy and girl had stood. 'We made it,' he said. 'We were always going to,' she said, and believed it, the heart knowing first."}, {'n': 6, 'title': 'Epilogue in Wildflowers', 'text': "love is worth the risk. In the coastal town of Seabrook, in the wildflowers, in the salt air, in every sunset: the whole story, still beginning, never ending.\n\nYears later, a plane ticket sits on the mantel still, a little faded, entirely cherished. The house is full of noise: children, dogs, her best friend Jess's children, the whole beautiful chaos of a life chosen.\n\nClaire Bennett walks the shore most evenings, sometimes alone, sometimes with him, always with the coastal town of Seabrook around her like a held breath. The sunsets haven't changed. She has — into someone who stays."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

